def minPath(grid, k):
    n = len(grid)
    m = n * n + 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    x, y = i + di, j + dj
