def tri(n):
    result = [1]
    if n == 0:
        return result
    result.append(3)
    for i in range(2, n + 1):
        if i % 2 == 0:
            result.append(1 + i // 2)
        else:
            result.append(result[i - 1] + result[i - 2] + (1 + (i + 1) // 2))
    return result
